export function machineSnapshot(spec){return Object.fromEntries(['name','machinePrice','standPrice','volume','maxTravel','speed','power','failure','quality','modelEnclosed','source','batchCapacity'].map(k=>[k,Array.isArray(spec[k])?[...spec[k]]:(k==='batchCapacity'?spec[k]||(spec.volume?.[0]>200?4:2):spec[k])??null]));}
export function legacyMachineSpec(type,paid){const rows={fdm:['Poste FDM compact · ancien',1,.12,.055,false],enclosed:['Poste FDM fermé · ancien',.8,.16,.035,true],pro:['Poste FDM pro · ancien',.65,.2,.025,true]},r=rows[type]||rows.fdm;return {name:r[0],machinePrice:paid,standPrice:0,volume:[300,300,300],maxTravel:null,speed:r[1],power:r[2],failure:r[3],quality:.96,modelEnclosed:r[4],source:null};}
export function fitsMachine(machine,order,spec){const d=order.dimensions;if(!Array.isArray(d))return true;const v=spec.volume||[300,300,300];return d[2]<=v[2]&&((d[0]<=v[0]&&d[1]<=v[1])||(d[1]<=v[0]&&d[0]<=v[1]));}
